package com.finsight.controller; import com.finsight.domain.*; import com.finsight.service.CreditApplicationService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/applications") public class ApplicationController {final CreditApplicationService service;public ApplicationController(CreditApplicationService s){service=s;}@GetMapping public List<CreditApplication> all(){return service.all();}@GetMapping("/{id}")public CreditApplication get(@PathVariable Long id){return service.get(id);}@PostMapping public CreditApplication create(@RequestBody Create r){return service.create(r.customerId(),r.requestedAmount(),r.tenureMonths());}@PostMapping("/{id}/risk-assessment")public CreditApplication assess(@PathVariable Long id){return service.assess(id);}@PostMapping("/{id}/decision")public CreditApplication decide(@PathVariable Long id,@RequestBody Decision r){return service.decide(id,r.decision(),r.reason());}@GetMapping("/{id}/audit")public List<AuditEvent> audit(@PathVariable Long id){return service.audit(id);}record Create(Long customerId,Double requestedAmount,Integer tenureMonths){}record Decision(String decision,String reason){}}
